{"command":"@'
$ErrorActionPreference = 'Stop'
$root = 'Script\Blueprint\Prefabs\Monsters'
$allLua = rg --files $root | Where-Object { $_ -like '*.lua' }

function Ensure-MonsterSpawnMgrRequire([string]$text) {
    if ($text -match 'Script\.Lin\.MonsSpawMgr') {
        return $text
    }

    $lines = $text -split "`r?`n", -1
    $insertIndex = -1
    for ($i = 0; $i -lt $lines.Length; $i++) {
        if ($lines[$i] -match '^local\s+\w+\s*=\s*UGCGameSystem\.UGCRequire\(') {
            $insertIndex = $i
        } elseif ($insertIndex -ge 0 -and $lines[$i] -notmatch '^local\s+\w+\s*=\s*UGCGameSystem\.UGCRequire\(') {
            break
        }
    }

    if ($insertIndex -lt 0) {
        for ($i = 0; $i -lt $lines.Length; $i++) {
            if ($lines[$i] -match '^local\s+\w+\s*=\s*\{\}') {
                $insertIndex = $i
                break
            }
        }
    }

    if ($insertIndex -lt 0) {
        throw "No insertion point for MonsSpawMgr require"
    }

    $before = @()
    if ($insertIndex -ge 0) { $before = $lines[0..$insertIndex] }
    $after = @()
    if ($insertIndex + 1 -lt $lines.Length) { $after = $lines[($insertIndex + 1)..($lines.Length - 1)] }
    return (($before + 'local MonsterSpawnMgr = UGCGameSystem.UGCRequire("Script.Lin.MonsSpawMgr")' + $after) -join "`r`n")
}

function Remove-LocalDisable([string]$text) {
    $pattern = '(?s)\r?\n?--\[\[----------------------禁用怪物碰撞------------------------\]\]\r?\nlocal function DisableMonsterCollision\(monster\)\r?\n.*?\r?\nend\r?\n'
    $text = [regex]::Replace($text, $pattern, "`r`n", 1)
    $pattern2 = '(?s)\r?\n?local function DisableMonsterCollision\(monster\)\r?\n.*?\r?\nend\r?\n'
    return [regex]::Replace($text, $pattern2, "`r`n", 1)
}

function Ensure-CollisionCall([string]$text) {
    $text = $text -replace 'DisableMonsterCollision\(self\)', 'MonsterSpawnMgr.DisableMonsterCollision(self)'
    if ($text -match 'MonsterSpawnMgr\.DisableMonsterCollision\(self\)') {
        return $text
    }

    $pattern = '(function\s+\w+:BPDie\([^\r\n]*\)\r?\n)'
    if ($text -notmatch $pattern) {
        return $text
    }

    return [regex]::Replace($text, $pattern, "`$1    MonsterSpawnMgr.DisableMonsterCollision(self)`r`n", 1)
}

function Ensure-FirstHitRunAway([string]$text) {
    if ($text -match '(?m)^function\s+BaseMons:PostTakeDamageEvent\(') {
        return $text
    }

    $method = "--[[----------------------首次受击随机移动后追击攻击者------------------------]]`r`nfunction BaseMons:PostTakeDamageEvent(Damage, EventInstigator, DamageCauser, DamageContext)`r`n    MonsterSpawnMgr.FirstHitRunAway(self, EventInstigator)`r`nend`r`n`r`n"
